@rendermode InteractiveServer
@using sv_c6e080c3c1f14b378bbdb0d0897a5a94.Components.Pages.Board
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Project Board</h3>

@if (_loading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @_error
    </div>
}
else
{
    <BoardSummaryBar TotalCount="_allTasks.Count"
                     TodoCount="GetTasksByStatus("To Do").Count"
                     InProgressCount="GetTasksByStatus("In Progress").Count"
                     DoneCount="GetTasksByStatus("Done").Count"
                     OverdueCount="_allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchTerm="@_searchTerm" SearchTermChanged="HandleSearchChanged" />

    <div class="row g-3">
        <KanbanColumn ColumnName="To Do"
                      Tasks="GetFilteredTasksByStatus("To Do")"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="@(id => MoveTask(id, "In Progress"))"
                      OnAddTask="@(model => AddTask(model, "To Do"))" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="GetFilteredTasksByStatus("In Progress")"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="@(id => MoveTask(id, "To Do"))"
                      OnMoveRight="@(id => MoveTask(id, "Done"))"
                      OnAddTask="@(model => AddTask(model, "In Progress"))" />

        <KanbanColumn ColumnName="Done"
                      Tasks="GetFilteredTasksByStatus("Done")"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="@(id => MoveTask(id, "In Progress"))"
                      OnAddTask="@(model => AddTask(model, "Done"))" />
    </div>
}

@code {
    private List<TaskItem> _allTasks = new();
    private string _searchTerm = string.Empty;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetTasksByStatus(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksByStatus(string status) =>
        _allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrEmpty(_searchTerm) ||
                        t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private void HandleSearchChanged(string term) => _searchTerm = term;

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.First(t => t.Id == taskId);
            _allTasks[_allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            _allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }
}
"}

